// Bundles definitions/*.json (the single source, DATA-02) into a generated
// Dart file so apps can load them without file access. Never edit the output.
//
// Usage (from tools/): dart run bin/gen_definitions.dart [--check]
// --check exits non-zero if the generated file is out of date (for CI/tests).
import 'dart:convert';
import 'dart:io';

const outPath =
    '../packages/category_definitions/lib/src/generated/bundled_definitions.g.dart';

void main(List<String> args) {
  final files =
      Directory('../definitions')
          .listSync()
          .whereType<File>()
          .where(
            (f) => f.path.endsWith('.json') && !f.path.endsWith('.temp.json'),
          )
          .toList()
        ..sort((a, b) => a.path.compareTo(b.path));

  final buf = StringBuffer()
    ..writeln(
      '// GENERATED by tools/bin/gen_definitions.dart from definitions/.',
    )
    ..writeln('// Do not edit by hand.')
    ..writeln()
    ..writeln(
      '/// Raw JSON of every bundled category definition, by file name.',
    )
    ..writeln('const bundledDefinitionSources = <String, String>{');
  for (final f in files) {
    final name = f.uri.pathSegments.last;
    // Re-encode to validate JSON and normalize whitespace.
    final json = jsonEncode(jsonDecode(f.readAsStringSync()));
    buf.writeln("  '$name': r'''$json''',");
  }
  buf.writeln('};');

  final out = File(outPath);
  final next = buf.toString();
  if (args.contains('--check')) {
    if (!out.existsSync() || out.readAsStringSync() != next) {
      stderr.writeln(
        '$outPath is stale. Run: dart run bin/gen_definitions.dart',
      );
      exit(1);
    }
    print('bundled definitions up to date');
    return;
  }
  out
    ..createSync(recursive: true)
    ..writeAsStringSync(next);
  print('wrote ${files.length} definition(s) to $outPath');
}
